import scala.collection.mutable

def twoSum(nums: Array[Int], target: Int): Array[Int] = {
  val seen = mutable.HashMap[Int, Int]()   // value -> index
  for (i <- nums.indices) {
    val need = target - nums(i)            // CHANGE: what completes this one?
    seen.get(need) match {
      case Some(j) => return Array(j, i)
      case None    => seen(nums(i)) = i    // store after the check
    }
  }
  Array.empty[Int]
}

