function longestAtMostK(s, k) {
  const count = new Map();
  let left = 0, best = 0;
  for (let right = 0; right < s.length; right++) {
    count.set(s[right], (count.get(s[right]) || 0) + 1);   // grow
    while (count.size > k) {                               // CHANGE: while invalid
      const d = s[left++];
      count.set(d, count.get(d) - 1);
      if (count.get(d) === 0) count.delete(d);             // shrink
    }
    best = Math.max(best, right - left + 1);               // valid: record
  }
  return best;
}

