use std::collections::HashMap;

fn longest_at_most_k(s: &str, k: usize) -> usize {
    let b = s.as_bytes();
    let mut count: HashMap<u8, usize> = HashMap::new();
    let (mut left, mut best) = (0, 0);
    for right in 0..b.len() {
        *count.entry(b[right]).or_insert(0) += 1; // grow
        while count.len() > k {                    // CHANGE: while invalid
            let d = b[left];
            let c = count.get_mut(&d).unwrap();
            *c -= 1;
            if *c == 0 { count.remove(&d); }
            left += 1;                             // shrink
        }
        best = best.max(right + 1 - left);         // valid: record
    }
    best
}

