import scala.collection.mutable

def longestAtMostK(s: String, k: Int): Int = {
  val count = mutable.HashMap[Char, Int]()
  var left = 0
  var best = 0
  for (right <- s.indices) {
    count(s(right)) = count.getOrElse(s(right), 0) + 1      // grow
    while (count.size > k) {                                // CHANGE: while invalid
      val d = s(left)
      count(d) -= 1
      if (count(d) == 0) count.remove(d)
      left += 1                                             // shrink
    }
    best = math.max(best, right - left + 1)                 // valid: record
  }
  best
}

