func isValid(s string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'} // CHANGE: closer -> opener
	stack := []rune{}
	for _, c := range s {
		if open, ok := pairs[c]; ok {
			if len(stack) == 0 || stack[len(stack)-1] != open {
				return false
			}
			stack = stack[:len(stack)-1]
		} else {
			stack = append(stack, c) // still open
		}
	}
	return len(stack) == 0
}

