	Val         int
	Left, Right *TreeNode
}

func levelOrder(root *TreeNode) [][]int {
	out := [][]int{}
	if root == nil {
		return out
	}
	q := []*TreeNode{root}
	for len(q) > 0 {
		level, next := []int{}, []*TreeNode{}
		for _, node := range q { // exactly the nodes of this level
			level = append(level, node.Val) // CHANGE: what to do with each node
			if node.Left != nil {
				next = append(next, node.Left)
			}
			if node.Right != nil {
				next = append(next, node.Right)
			}
		}
		out = append(out, level)
		q = next
	}
	return out
}

