vector<vector<int>> levelOrder(TreeNode* root) {
    vector<vector<int>> out;
    queue<TreeNode*> q;
    if (root) q.push(root);
    while (!q.empty()) {
        vector<int> level;
        for (int k = (int)q.size(); k > 0; k--) {   // exactly the nodes of this level
            TreeNode* node = q.front(); q.pop();
            level.push_back(node->val);            // CHANGE: what to do with each node
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        out.push_back(level);
    }
    return out;
