use std::cell::RefCell;
use std::rc::Rc;

pub struct TreeNode { pub val: i32, pub left: Option<Rc<RefCell<TreeNode>>>, pub right: Option<Rc<RefCell<TreeNode>>> }
type Node = Option<Rc<RefCell<TreeNode>>>;   // LeetCode's tree type

use std::collections::VecDeque;

fn level_order(root: Node) -> Vec<Vec<i32>> {
    let mut out = Vec::new();
    let mut q: VecDeque<Rc<RefCell<TreeNode>>> = root.into_iter().collect();
    while !q.is_empty() {
        let mut level = Vec::new();
        for _ in 0..q.len() { // exactly the nodes of this level
            let node = q.pop_front().unwrap();
            let n = node.borrow();
            level.push(n.val); // CHANGE: what to do with each node
            if let Some(l) = n.left.clone() { q.push_back(l); }
            if let Some(r) = n.right.clone() { q.push_back(r); }
        }
        out.push(level);
    }
    out
}

