def levelOrder(root: TreeNode): List[List[Int]] = {
  val out = scala.collection.mutable.ListBuffer[List[Int]]()
  var level = if (root == null) List.empty[TreeNode] else List(root)
  while (level.nonEmpty) {
    out += level.map(_.value)                                  // CHANGE: per node
    level = level.flatMap(n => List(n.left, n.right).filter(_ != null))
  }
  out.toList
}

