def kth_largest(nums, k):
    heap = []                          # min-heap holding the k largest so far
    for x in nums:
        heapq.heappush(heap, x)        # CHANGE: the key (negate for k smallest)
        if len(heap) > k:
            heapq.heappop(heap)        # drop the smallest of the k + 1
    return heap[0]                     # the k-th largest

