function dijkstra(n, edges, src) {         // [u, v, w], directed, w >= 0
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) adj[u].push([v, w]);
  const dist = new Array(n).fill(Infinity); dist[src] = 0;
  const heap = [[0, src]];                 // a small binary heap ordered by distance
  const push = x => { heap.push(x); let i = heap.length - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (heap[p][0] <= heap[i][0]) break; [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
  const pop = () => { const top = heap[0], last = heap.pop();
    if (heap.length) { heap[0] = last; let i = 0;
      for (;;) { const l = 2 * i + 1, r = l + 1; let m = i;
        if (l < heap.length && heap[l][0] < heap[m][0]) m = l; if (r < heap.length && heap[r][0] < heap[m][0]) m = r;
        if (m === i) break; [heap[m], heap[i]] = [heap[i], heap[m]]; i = m; } }
    return top; };
  while (heap.length) {
    const [d, u] = pop();
    if (d > dist[u]) continue;             // stale entry
    for (const [v, w] of adj[u]) {
      const nd = d + w;                    // CHANGE: how a path's cost grows
      if (nd < dist[v]) { dist[v] = nd; push([nd, v]); }
    }
  }
  return dist;
}

