import (
	"container/heap"
	"math"
)

type item struct{ d, u int }
type pq []item

func (h pq) Len() int           { return len(h) }
func (h pq) Less(i, j int) bool { return h[i].d < h[j].d }
func (h pq) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *pq) Push(x any)        { *h = append(*h, x.(item)) }
func (h *pq) Pop() any          { o := *h; x := o[len(o)-1]; *h = o[:len(o)-1]; return x }

func dijkstra(n int, edges [][3]int, src int) []int { // {u, v, w}, directed, w >= 0
	adj := make([][][2]int, n)
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], [2]int{e[1], e[2]})
	}
	dist := make([]int, n)
	for i := range dist {
		dist[i] = math.MaxInt
	}
	dist[src] = 0
	h := &pq{{0, src}}
	for h.Len() > 0 {
		it := heap.Pop(h).(item)
		if it.d > dist[it.u] {
			continue // stale entry
		}
		for _, e := range adj[it.u] {
			if nd := it.d + e[1]; nd < dist[e[0]] { // CHANGE: how a path's cost grows
				dist[e[0]] = nd
				heap.Push(h, item{nd, e[0]})
			}
