class Trie:
    def __init__(self):
        self.kids, self.end, self.count = {}, False, 0   # count: words below this node

    def insert(self, word):
        node = self
        for c in word:
            node = node.kids.setdefault(c, Trie())
            node.count += 1                # CHANGE: what each node remembers
        node.end = True

    def _walk(self, s):
        node = self
        for c in s:
            node = node.kids.get(c)
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.end   # a prefix alone is not a word

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

    def count_prefix(self, prefix):
        node = self._walk(prefix)
        return node.count if node else 0

