func NewTrie() *Trie { return &Trie{kids: map[rune]*Trie{}} }

func (t *Trie) Insert(word string) {
	node := t
	for _, c := range word {
		if node.kids[c] == nil {
			node.kids[c] = NewTrie()
		}
		node = node.kids[c]
		node.count++ // CHANGE: what each node remembers
	}
	node.end = true
}

func (t *Trie) walk(s string) *Trie {
	node := t
	for _, c := range s {
		if node = node.kids[c]; node == nil {
			return nil
		}
	}
	return node
}

