struct Trie {
    struct Node { array<int, 26> kids; bool end = false; int count = 0; Node() { kids.fill(-1); } };
    vector<Node> nodes{Node()};                           // node 0 is the root
    void insert(const string& word) {                     // lowercase a-z
        int cur = 0;
        for (char ch : word) {
            int c = ch - 'a';
            if (nodes[cur].kids[c] < 0) { nodes[cur].kids[c] = nodes.size(); nodes.emplace_back(); }
            cur = nodes[cur].kids[c];
            nodes[cur].count++;                           // CHANGE: what each node remembers
        }
        nodes[cur].end = true;
    }
    int walk(const string& s) const {
        int cur = 0;
        for (char ch : s) if ((cur = nodes[cur].kids[ch - 'a']) < 0) return -1;
        return cur;
    }
    bool search(const string& w) const { int n = walk(w); return n >= 0 && nodes[n].end; }
    bool startsWith(const string& p) const { return walk(p) >= 0; }
    int countPrefix(const string& p) const { int n = walk(p); return n < 0 ? 0 : nodes[n].count; }
};

