import "container/list"

type entry struct{ key, value int }

type LRUCache struct {
	cap   int
	order *list.List // front = most recent
	nodes map[int]*list.Element
}

func NewLRU(capacity int) *LRUCache {
	return &LRUCache{capacity, list.New(), map[int]*list.Element{}}
}

func (c *LRUCache) Get(key int) int {
	el, ok := c.nodes[key]
	if !ok {
		return -1
	}
	c.order.MoveToFront(el)
	return el.Value.(*entry).value
}

func (c *LRUCache) Put(key, value int) {
	if el, ok := c.nodes[key]; ok {
		el.Value.(*entry).value = value
		c.order.MoveToFront(el)
		return
	}
	c.nodes[key] = c.order.PushFront(&entry{key, value})
	if c.order.Len() > c.cap { // CHANGE: the eviction rule
		last := c.order.Back()
		c.order.Remove(last)
		delete(c.nodes, last.Value.(*entry).key)
	}
}

