class LRUCache {
    int cap;
    list<pair<int, int>> order;                                 // front = most recent
    unordered_map<int, list<pair<int, int>>::iterator> nodes;   // key -> node in order
public:
    LRUCache(int capacity) : cap(capacity) {}
    int get(int key) {
        auto it = nodes.find(key);
        if (it == nodes.end()) return -1;
        order.splice(order.begin(), order, it->second);         // move to front in O(1)
        return it->second->second;
    }
    void put(int key, int value) {
        if (auto it = nodes.find(key); it != nodes.end()) {
            it->second->second = value;
            order.splice(order.begin(), order, it->second);
            return;
        }
        order.push_front({key, value});
        nodes[key] = order.begin();
        if ((int)order.size() > cap) {                          // CHANGE: the eviction rule
            nodes.erase(order.back().first);
            order.pop_back();
        }
    }
};

