use std::collections::{BTreeMap, HashMap};

// A map from key to (value, last use) plus a BTreeMap from last use to key: O(log n) per call.
struct LruCache { cap: usize, tick: u64, data: HashMap<i32, (i32, u64)>, by_use: BTreeMap<u64, i32> }

impl LruCache {
    fn new(cap: usize) -> Self { LruCache { cap, tick: 0, data: HashMap::new(), by_use: BTreeMap::new() } }
    fn touch(&mut self, key: i32, value: i32) {
        self.tick += 1;
        if let Some((_, old)) = self.data.insert(key, (value, self.tick)) { self.by_use.remove(&old); }
        self.by_use.insert(self.tick, key);
    }
    fn get(&mut self, key: i32) -> i32 {
        match self.data.get(&key).copied() {
            Some((v, _)) => { self.touch(key, v); v }
            None => -1,
        }
    }
    fn put(&mut self, key: i32, value: i32) {
        self.touch(key, value);
        if self.data.len() > self.cap { // CHANGE: the eviction rule
            let (&t, &old) = self.by_use.iter().next().unwrap(); // least recent
            self.by_use.remove(&t);
            self.data.remove(&old);
        }
    }
}

