fn prefix_sums(a: &[i64]) -> Vec<i64> {
    let mut p = vec![0i64; a.len() + 1];
    for i in 0..a.len() { p[i + 1] = p[i] + a[i]; } // sum(l..r) = p[r+1] - p[l]
    p
}

fn count_subarrays_with_sum(a: &[i64], k: i64) -> usize {
    let mut seen: HashMap<i64, usize> = HashMap::from([(0, 1)]); // prefix -> times seen
    let (mut total, mut count) = (0i64, 0usize);
    for &x in a {
        total += x;
        count += seen.get(&(total - k)).copied().unwrap_or(0); // CHANGE: which earlier prefix?
        *seen.entry(total).or_insert(0) += 1;
    }
    count
}

