import scala.collection.mutable

def prefixSums(a: Array[Int]): Array[Long] = {
  val p = new Array[Long](a.length + 1)
  for (i <- a.indices) p(i + 1) = p(i) + a(i)     // sum(l..r) = p(r+1) - p(l)
  p
}

def countSubarraysWithSum(a: Array[Int], k: Int): Int = {
  val seen = mutable.HashMap[Long, Int](0L -> 1)  // prefix sum -> how many times
  var total = 0L
  var count = 0
  for (x <- a) {
    total += x
    count += seen.getOrElse(total - k, 0)         // CHANGE: which earlier prefix?
    seen(total) = seen.getOrElse(total, 0) + 1
  }
  count
}

