function rotate(m) {                       // n x n, clockwise, in place
  const n = m.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) [m[i][j], m[j][i]] = [m[j][i], m[i][j]];   // transpose
  for (const row of m) row.reverse();      // CHANGE: direction
}

