func rotate(m [][]int) { // n x n, clockwise, in place
	n := len(m)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ { // transpose
			m[i][j], m[j][i] = m[j][i], m[i][j]
		}
	}
	for _, row := range m { // CHANGE: direction
		for l, r := 0, n-1; l < r; l, r = l+1, r-1 {
			row[l], row[r] = row[r], row[l]
		}
	}
}

