fn rotate(m: &mut Vec<Vec<i32>>) { // n x n, clockwise, in place
    let n = m.len();
    for i in 0..n {
        for j in i + 1..n { // transpose
            let t = m[i][j];
            m[i][j] = m[j][i];
            m[j][i] = t;
        }
    }
    for row in m.iter_mut() { row.reverse(); } // CHANGE: direction
}

