function distToNearest(grid) {             // 0 = source, 1 = open, 2 = wall
  const R = grid.length, C = grid[0].length;
  const dist = grid.map(row => row.map(() => -1)), q = [];
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++)
    if (grid[r][c] === 0) { dist[r][c] = 0; q.push([r, c]); }   // CHANGE: sources
  for (let h = 0; h < q.length; h++) {
    const [r, c] = q[h];
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {   // CHANGE: moves
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < R && nc >= 0 && nc < C && dist[nr][nc] === -1 && grid[nr][nc] !== 2) {
        dist[nr][nc] = dist[r][c] + 1; q.push([nr, nc]);
      }
    }
  }
  return dist;
}

