func distToNearest(grid [][]int) [][]int { // 0 = source, 1 = open, 2 = wall
	R, C := len(grid), len(grid[0])
	dist := make([][]int, R)
	q := [][2]int{}
	for r := range grid {
		dist[r] = make([]int, C)
		for c := range grid[r] {
			dist[r][c] = -1
			if grid[r][c] == 0 { // CHANGE: every source starts at 0
				dist[r][c] = 0
				q = append(q, [2]int{r, c})
			}
		}
	}
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}} // CHANGE: the moves
	for h := 0; h < len(q); h++ {
		r, c := q[h][0], q[h][1]
		for _, d := range dirs {
			nr, nc := r+d[0], c+d[1]
			if nr >= 0 && nr < R && nc >= 0 && nc < C && dist[nr][nc] == -1 && grid[nr][nc] != 2 {
				dist[nr][nc] = dist[r][c] + 1
				q = append(q, [2]int{nr, nc})
			}
		}
	}
	return dist
}

