vector<vector<int>> distToNearest(const vector<vector<int>>& grid) {   // 0 source, 2 wall
    int R = grid.size(), C = grid[0].size();
    vector<vector<int>> dist(R, vector<int>(C, -1));
    queue<pair<int, int>> q;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++)
            if (grid[r][c] == 0) { dist[r][c] = 0; q.push({r, c}); }   // CHANGE: sources
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};                  // CHANGE: moves
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && dist[nr][nc] == -1 && grid[nr][nc] != 2) {
                dist[nr][nc] = dist[r][c] + 1; q.push({nr, nc});
            }
        }
    }
    return dist;
}

