use std::collections::VecDeque;

fn dist_to_nearest(grid: &[Vec<i32>]) -> Vec<Vec<i32>> { // 0 = source, 2 = wall
    let (rows, cols) = (grid.len(), grid[0].len());
    let mut dist = vec![vec![-1; cols]; rows];
    let mut q = VecDeque::new();
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] == 0 { dist[r][c] = 0; q.push_back((r, c)); } // CHANGE: sources
        }
    }
    while let Some((r, c)) = q.pop_front() {
        for (dr, dc) in [(1i32, 0i32), (-1, 0), (0, 1), (0, -1)] { // CHANGE: moves
            let (nr, nc) = (r as i32 + dr, c as i32 + dc);
            if nr < 0 || nc < 0 || nr >= rows as i32 || nc >= cols as i32 { continue; }
            let (nr, nc) = (nr as usize, nc as usize);
            if dist[nr][nc] == -1 && grid[nr][nc] != 2 {
                dist[nr][nc] = dist[r][c] + 1;
                q.push_back((nr, nc));
            }
        }
    }
    dist
}

