def distToNearest(grid: Array[Array[Int]]): Array[Array[Int]] = {   // 0 source, 2 wall
  val (rows, cols) = (grid.length, grid(0).length)
  val dist = Array.fill(rows, cols)(-1)
  val q = scala.collection.mutable.Queue[(Int, Int)]()
  for (r <- 0 until rows; c <- 0 until cols if grid(r)(c) == 0) { dist(r)(c) = 0; q.enqueue((r, c)) }
  val moves = Seq((1, 0), (-1, 0), (0, 1), (0, -1))                  // CHANGE: moves
  while (q.nonEmpty) {
    val (r, c) = q.dequeue()
    for ((dr, dc) <- moves) {
      val (nr, nc) = (r + dr, c + dc)
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && dist(nr)(nc) == -1 && grid(nr)(nc) != 2) {
        dist(nr)(nc) = dist(r)(c) + 1; q.enqueue((nr, nc))
      }
    }
  }
  dist
}

