def shipWithinDays(weights: Array[Int], days: Int): Int = {
  def feasible(cap: Int): Boolean = {          // CHANGE: simulate with this candidate
    var need = 1
    var load = 0
    for (w <- weights) { if (load + w > cap) { need += 1; load = 0 }; load += w }
    need <= days
  }
  var lo = weights.max
  var hi = weights.sum
  while (lo < hi) {
    val mid = lo + (hi - lo) / 2
    if (feasible(mid)) hi = mid else lo = mid + 1
