use std::cell::RefCell;
use std::rc::Rc;

pub struct TreeNode { pub val: i32, pub left: Option<Rc<RefCell<TreeNode>>>, pub right: Option<Rc<RefCell<TreeNode>>> }
type Node = Option<Rc<RefCell<TreeNode>>>;   // LeetCode's tree type

fn diameter(root: Node) -> i32 {
    fn dfs(node: &Node, best: &mut i32) -> i32 { // returns the height in nodes
        match node {
            None => 0, // CHANGE: the value for an empty tree
            Some(n) => {
                let n = n.borrow();
                let (l, r) = (dfs(&n.left, best), dfs(&n.right, best));
                *best = (*best).max(l + r); // CHANGE: the path that bends here
                1 + l.max(r)                // CHANGE: one side only, for the parent
            }
        }
    }
    let mut best = 0;
    dfs(&root, &mut best);
    best
}

