func numIslands(grid [][]byte) int {
	R, C := len(grid), len(grid[0])
	seen := make([][]bool, R)
	for i := range seen {
		seen[i] = make([]bool, C)
	}
	var dfs func(r, c int)
	dfs = func(r, c int) {
		if r < 0 || r >= R || c < 0 || c >= C || seen[r][c] || grid[r][c] != '1' { // CHANGE
			return
		}
		seen[r][c] = true // mark before visiting the neighbours
		dfs(r+1, c)
		dfs(r-1, c)
		dfs(r, c+1)
		dfs(r, c-1)
	}
	count := 0
	for r := 0; r < R; r++ {
		for c := 0; c < C; c++ {
			if grid[r][c] == '1' && !seen[r][c] {
				count++ // a new region
				dfs(r, c)
			}
		}
	}
	return count
}

