fn num_islands(grid: &[Vec<char>]) -> usize {
    let (rows, cols) = (grid.len(), grid[0].len());
    let mut seen = vec![vec![false; cols]; rows];
    let mut count = 0;
    for r in 0..rows {
        for c in 0..cols {
            if grid[r][c] != '1' || seen[r][c] { continue; }
            count += 1; // a new region
            let mut stack = vec![(r, c)];
            seen[r][c] = true;
            while let Some((y, x)) = stack.pop() {
                let near = [(y + 1, x), (y.wrapping_sub(1), x), (y, x + 1), (y, x.wrapping_sub(1))];
                for (ny, nx) in near {
                    if ny < rows && nx < cols && !seen[ny][nx] && grid[ny][nx] == '1' { // CHANGE
                        seen[ny][nx] = true; // mark before visiting
                        stack.push((ny, nx));
                    }
                }
            }
        }
    }
    count
}

