function floydWarshall(n, edges) {         // [u, v, w], directed
  const dist = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 0 : Infinity)));
  for (const [u, v, w] of edges) dist[u][v] = Math.min(dist[u][v], w);
  for (let k = 0; k < n; k++)              // k outermost
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];   // CHANGE
  return dist;
}

code.go:
import "math"

func floydWarshall(n int, edges [][3]int) [][]int { // {u, v, w}, directed
	const INF = math.MaxInt / 2 // half: INF + INF does not overflow
	dist := make([][]int, n)
	for i := range dist {
		dist[i] = make([]int, n)
		for j := range dist[i] {
			if i != j {
				dist[i][j] = INF
			}
		}
	}
	for _, e := range edges {
		dist[e[0]][e[1]] = min(dist[e[0]][e[1]], e[2])
	}
	for k := 0; k < n; k++ { // k outermost
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				if dist[i][k]+dist[k][j] < dist[i][j] { // CHANGE: how paths combine
					dist[i][j] = dist[i][k] + dist[k][j]
				}
			}
		}
	}
	return dist
}

