vector<vector<long long>> floydWarshall(int n, const vector<array<int, 3>>& edges) {
    const long long INF = LLONG_MAX / 4;                // INF + INF does not overflow
    vector<vector<long long>> dist(n, vector<long long>(n, INF));
    for (int i = 0; i < n; i++) dist[i][i] = 0;
    for (auto& e : edges) dist[e[0]][e[1]] = min(dist[e[0]][e[1]], (long long)e[2]);
    for (int k = 0; k < n; k++)                         // k outermost
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);   // CHANGE
    return dist;
}

