    let mut dist = vec![vec![INF; n]; n];
    for i in 0..n { dist[i][i] = 0; }
    for &(u, v, w) in edges { dist[u][v] = dist[u][v].min(w); }
    for k in 0..n { // k outermost
        for i in 0..n {
            for j in 0..n {
                let via = dist[i][k] + dist[k][j]; // CHANGE: how paths combine
                if via < dist[i][j] { dist[i][j] = via; }
            }
        }
    }
    dist
