def floydWarshall(n: Int, edges: Seq[(Int, Int, Int)]): Array[Array[Long]] = {
  val INF = Long.MaxValue / 4                     // INF + INF does not overflow
  val dist = Array.tabulate(n, n)((i, j) => if (i == j) 0L else INF)
  for ((u, v, w) <- edges) dist(u)(v) = math.min(dist(u)(v), w.toLong)
  for (k <- 0 until n; i <- 0 until n; j <- 0 until n)   // k outermost
    dist(i)(j) = math.min(dist(i)(j), dist(i)(k) + dist(k)(j))   // CHANGE
  dist
}

