def kthSmallest(arr: Array[Int], k: Int): Int = {   // k from 1
  val a = arr.clone()
  val rnd = new scala.util.Random(12345)
  var (lo, hi) = (0, a.length - 1)
  val target = k - 1
  def swap(i: Int, j: Int): Unit = { val t = a(i); a(i) = a(j); a(j) = t }
  while (true) {
    swap(lo + rnd.nextInt(hi - lo + 1), hi)         // random pivot
    var store = lo
    for (i <- lo until hi) if (a(i) < a(hi)) { swap(i, store); store += 1 }   // CHANGE
    swap(store, hi)
    if (store == target) return a(store)
    if (store < target) lo = store + 1 else hi = store - 1
  }
  -1
}

