def kmp_search(text, pat):
    if not pat:
        return 0
    lps, k = [0] * len(pat), 0             # lps[i]: longest border of pat[0..i]
    for i in range(1, len(pat)):
        while k and pat[i] != pat[k]:
            k = lps[k - 1]                 # fall back to a shorter border
        if pat[i] == pat[k]:
            k += 1
        lps[i] = k
    j = 0                                  # characters of pat matched so far
    for i, c in enumerate(text):
        while j and c != pat[j]:
            j = lps[j - 1]
        if c == pat[j]:
            j += 1
        if j == len(pat):
            return i - j + 1               # CHANGE: collect all matches with j = lps[j-1]
    return -1

