use std::cell::RefCell;
use std::rc::Rc;

pub struct TreeNode { pub val: i32, pub left: Option<Rc<RefCell<TreeNode>>>, pub right: Option<Rc<RefCell<TreeNode>>> }
type Node = Option<Rc<RefCell<TreeNode>>>;   // LeetCode's tree type

use std::collections::HashMap;

fn build_tree(preorder: &[i32], inorder: &[i32]) -> Node {
    fn build(lo: i64, hi: i64, pre: &[i32], p: &mut usize, wh: &HashMap<i32, i64>) -> Node {
        if lo > hi { return None; }
        let val = pre[*p];
        *p += 1;
        let mid = wh[&val];
        let left = build(lo, mid - 1, pre, p, wh); // left first: preorder order
        let right = build(mid + 1, hi, pre, p, wh);
        Some(Rc::new(RefCell::new(TreeNode { val, left, right })))
    }
    let wh: HashMap<i32, i64> = inorder.iter().enumerate().map(|(i, &v)| (v, i as i64)).collect();
    let mut p = 0;
    build(0, inorder.len() as i64 - 1, preorder, &mut p, &wh)
}

