fn kth_smallest(root: Node, mut k: i32) -> Option<i32> {
    let mut stack: Vec<Rc<RefCell<TreeNode>>> = Vec::new();
    let mut node = root;
    while node.is_some() || !stack.is_empty() {
        while let Some(n) = node { // go as far left as possible
            node = n.borrow().left.clone();
            stack.push(n);
        }
        let n = stack.pop().unwrap(); // the next value in sorted order
        k -= 1;
        if k == 0 { return Some(n.borrow().val); } // CHANGE: per sorted value
        node = n.borrow().right.clone();
    }
    None
}

