func mstCost(n int, edges [][3]int) int { // {w, u, v}, undirected
	sort.Slice(edges, func(i, j int) bool { return edges[i][0] < edges[j][0] })
	parent := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	var find func(int) int
	find = func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]] // path halving
			x = parent[x]
		}
		return x
	}
	total, used := 0, 0
	for _, e := range edges { // lightest first
		ru, rv := find(e[1]), find(e[2])
		if ru == rv {
			continue // would close a cycle
		}
		parent[ru] = rv
		total += e[0] // CHANGE: what to collect
		if used++; used == n-1 {
			break
		}
	}
	if used != n-1 {
		return -1
	}
	return total
}

