fn mst_cost(n: usize, mut edges: Vec<(i64, usize, usize)>) -> i64 { // (w, u, v), undirected
    fn find(p: &mut Vec<usize>, mut x: usize) -> usize {
        while p[x] != x { p[x] = p[p[x]]; x = p[x]; } // path halving
        x
    }
    edges.sort(); // lightest first
    let mut parent: Vec<usize> = (0..n).collect();
    let (mut total, mut used) = (0, 0);
    for (w, u, v) in edges {
        let (ru, rv) = (find(&mut parent, u), find(&mut parent, v));
        if ru == rv { continue; } // would close a cycle
        parent[ru] = rv;
        total += w; // CHANGE: what to collect
        used += 1;
        if used == n - 1 { break; }
    }
    if used + 1 == n || n == 0 { total } else { -1 }
}

