import "math"

func minPathSum(grid [][]int) int {
	C := len(grid[0])
	dp := make([]int, C) // dp[c]: best cost to reach (row, c)
	for c := 1; c < C; c++ {
		dp[c] = math.MaxInt / 2
	}
	for _, row := range grid {
		for c := 0; c < C; c++ {
			best := dp[c] // from above
			if c > 0 && dp[c-1] < best {
				best = dp[c-1] // from the left
			}
			dp[c] = row[c] + best // CHANGE: the recurrence
		}
	}
	return dp[C-1]
}

