def longest_pal_subseq(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]           # dp[i][j]: answer for s[i..j]
    for i in range(n):
        dp[i][i] = 1                           # length 1
    for length in range(2, n + 1):             # shorter ranges first
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:                   # CHANGE: combine the inner ranges
                dp[i][j] = 2 + (dp[i + 1][j - 1] if i + 1 <= j - 1 else 0)
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1] if n else 0

