from functools import lru_cache

def longest_increasing_path(m):
    R, C = len(m), len(m[0])
    @lru_cache(maxsize=None)
    def best(r, c):                        # longest path starting at (r, c)
        out = 1
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < R and 0 <= nc < C and m[nr][nc] > m[r][c]:   # CHANGE: the moves
                out = max(out, 1 + best(nr, nc))
        return out
    return max(best(r, c) for r in range(R) for c in range(C))

