function longestIncreasingPath(m) {
  const R = m.length, C = m[0].length, memo = m.map(row => row.map(() => 0));
  const best = (r, c) => {                 // longest path starting at (r, c)
    if (memo[r][c]) return memo[r][c];
    let out = 1;
    for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]])
      if (nr >= 0 && nr < R && nc >= 0 && nc < C && m[nr][nc] > m[r][c])   // CHANGE: moves
        out = Math.max(out, 1 + best(nr, nc));
    return (memo[r][c] = out);
  };
  let ans = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) ans = Math.max(ans, best(r, c));
  return ans;
