func longestIncreasingPath(m [][]int) int {
	R, C := len(m), len(m[0])
	memo := make([][]int, R)
	for i := range memo {
		memo[i] = make([]int, C)
	}
	var best func(r, c int) int // longest path starting at (r, c)
	best = func(r, c int) int {
		if memo[r][c] > 0 {
			return memo[r][c]
		}
		out := 1
		for _, d := range [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}} {
			nr, nc := r+d[0], c+d[1]
			if nr >= 0 && nr < R && nc >= 0 && nc < C && m[nr][nc] > m[r][c] { // CHANGE: moves
				out = max(out, 1+best(nr, nc))
			}
		}
		memo[r][c] = out
		return out
	}
	ans := 0
	for r := 0; r < R; r++ {
		for c := 0; c < C; c++ {
			ans = max(ans, best(r, c))
		}
	}
	return ans
}

