function minAssignment(cost) {             // cost[worker][task], n x n
  const n = cost.length, full = (1 << n) - 1, dp = new Array(1 << n).fill(Infinity);
  dp[0] = 0;
  for (let mask = 0; mask < full; mask++) {
    if (dp[mask] === Infinity) continue;
    let k = 0; for (let x = mask; x; x &= x - 1) k++;   // popcount: the next worker
    for (let t = 0; t < n; t++)
      if (!(mask & (1 << t))) {
        const nxt = mask | (1 << t);
        dp[nxt] = Math.min(dp[nxt], dp[mask] + cost[k][t]);   // CHANGE: the transition
      }
  }
  return dp[full];
}

