import (
	"math"
	"math/bits"
)

func minAssignment(cost [][]int) int { // cost[worker][task], n x n
	n := len(cost)
	full := 1<<n - 1
	dp := make([]int, 1<<n)
	for i := range dp {
		dp[i] = math.MaxInt
	}
	dp[0] = 0
	for mask := 0; mask < full; mask++ { // smaller masks first
		if dp[mask] == math.MaxInt {
			continue
		}
		k := bits.OnesCount(uint(mask)) // the next worker
		for t := 0; t < n; t++ {
			if mask&(1<<t) == 0 { // task t is free
				nxt := mask | 1<<t
				dp[nxt] = min(dp[nxt], dp[mask]+cost[k][t]) // CHANGE: the transition
			}
		}
	}
	return dp[full]
}

