type SegTree struct {
	n    int
	tree []int // sums; leaves are tree[n:]
}

func NewSegTree(a []int) *SegTree {
	n := len(a)
	t := &SegTree{n, make([]int, 2*n)}
	copy(t.tree[n:], a)
	for i := n - 1; i > 0; i-- {
		t.tree[i] = t.tree[2*i] + t.tree[2*i+1] // CHANGE: combine
	}
	return t
}

func (t *SegTree) Update(i, value int) {
	i += t.n
	t.tree[i] = value
	for i /= 2; i >= 1; i /= 2 {
		t.tree[i] = t.tree[2*i] + t.tree[2*i+1]
	}
}

func (t *SegTree) Query(l, r int) int { // a[l..r), r exclusive
	res := 0 // CHANGE: the identity value
	for l, r = l+t.n, r+t.n; l < r; l, r = l/2, r/2 {
		if l&1 == 1 {
			res += t.tree[l]
			l++
		}
		if r&1 == 1 {
			r--
			res += t.tree[r]
		}
	}
	return res
}

