impl SegTree {
    fn new(a: &[i64]) -> Self {
        let n = a.len();
        let mut tree = vec![0; 2 * n];
        tree[n..].copy_from_slice(a);
        for i in (1..n).rev() { tree[i] = tree[2 * i] + tree[2 * i + 1]; } // CHANGE: combine
        SegTree { n, tree }
    }
    fn update(&mut self, i: usize, value: i64) {
        let mut i = i + self.n;
        self.tree[i] = value;
        while i > 1 { i /= 2; self.tree[i] = self.tree[2 * i] + self.tree[2 * i + 1]; }
    }
    fn query(&self, l: usize, r: usize) -> i64 { // a[l..r), r exclusive
        let (mut l, mut r, mut res) = (l + self.n, r + self.n, 0); // CHANGE: identity
        while l < r {
            if l & 1 == 1 { res += self.tree[l]; l += 1; }
            if r & 1 == 1 { r -= 1; res += self.tree[r]; }
            l /= 2;
            r /= 2;
        }
        res
    }
}

