import "sort"

func maxOverlap(intervals [][2]int) int { // [start, end), end exclusive
	events := make([][2]int, 0, 2*len(intervals))
	for _, iv := range intervals {
		events = append(events, [2]int{iv[0], 1}, [2]int{iv[1], -1}) // CHANGE: weights
	}
	sort.Slice(events, func(i, j int) bool {
		if events[i][0] != events[j][0] {
			return events[i][0] < events[j][0]
		}
		return events[i][1] < events[j][1] // -1 before +1
	})
	active, best := 0, 0
	for _, e := range events {
		active += e[1]
		if active > best {
			best = active
		}
	}
	return best
}

func applyRangeAdds(n int, updates [][3]int) []int { // {l, r, v}, inclusive
	d := make([]int, n+1)
	for _, u := range updates {
		d[u[0]] += u[2]
		d[u[1]+1] -= u[2]
	}
	out, run := make([]int, n), 0
	for i := 0; i < n; i++ {
		run += d[i]
		out[i] = run
	}
	return out
}

