def isRobotBounded(instructions: String): Boolean = {
  val dirs = Array((0, 1), (1, 0), (0, -1), (-1, 0))   // north, east, south, west
  var (x, y, d) = (0, 0, 0)
  for (c <- instructions) c match {                    // CHANGE: the rules
    case 'G' => x += dirs(d)._1; y += dirs(d)._2
    case 'R' => d = (d + 1) % 4
    case _   => d = (d + 3) % 4
  }
  (x == 0 && y == 0) || d != 0
}
